def most_frequent_word(words):
    counts = {}
    for i in range(len(words) - 1):
        word = words[i]
        counts[word] = counts.get(word, 0) + 1
    best = ""
    best_count = 0
    for word in words:
        if counts.get(word, 0) > best_count:
            best = word
            best_count = counts[word]
    return best
